window.products.push({"id":725740,"name":"Teresa Collins, 8x10 I Am Enough Art Print Set, Wall Room Decor - 5 Sheets","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41NAtQd0RqL._AC_.jpg","description":"Empower yourself visually in your home, office, bedroom, or anywhere in your home! These 5 powerful prints are printed on 8x10 high quality thick glossy paper. Includes: I Am Enough I Am Enough Be You. Be You. Make Yourself Proud Make Yourself Proud You Are the Star of Your Life You Are the Star of Your Life Stop Comparing Yourself to Others Stop Comparing Yourself to Others As a GIRL BOSS of a successful worldwide brand, Teresa Collins is passionately and purposely designing products, apparel, hosts events, and travels the world to speak and teach workshops. Teresa has become a successful woman entrepreneur after and despite her setbacks along the way. She believes FAILURE IS NOT AN OPTION.","images":["https://m.media-amazon.com/images/I/41NAtQd0RqL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Teresa Collins","source_asin":"B0844TPFYN","category_path":"Home & Kitchen"},"sku":"BM-725740","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0844TPFYN","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0844TPFYN","price_pending":true,"merchant_ready":false});
